head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > setTimeout]<br/>특정 함수를 setTimeout 으로 등록하여 일정 시간 후에 실행되도록 합니다.",
    "validation" : [
        "func(필수) 파라미터로 일정 시간 후에 실행할 함수를 설정할 수 있어야 합니다.",
        "options(필수) 파라미터로 타이머 설정 옵션을 설정할 수 있어야 합니다.",
        "options.key(선택) 파라미터로 타이머를 식별하기 위한 고유 키를 설정할 수 있어야 합니다.",
        "options.key(선택) 파라미터 생략 시 func.toString().slice(0, 30) 값이 키로 사용되어야 합니다.",
        "동일 키로 반복 호출 시 이전 타이머를 취소하고 새로 등록해야 합니다.",
        "options.delay(선택) 파라미터로 지연 시간을 밀리초 단위로 설정할 수 있어야 합니다.",
        "options.delay(선택) 파라미터 생략 시 options.max 값을, 둘 다 설정하지 않으면 기본값 1 이 적용되어야 합니다.",
        "등록된 타이머의 키 값을 반환해야 합니다.",
        "SPA 모드에서 페이지 이동 시 이 메소드로 등록한 타이머가 자동으로 제거되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    var keyList = $p.getTimeoutKeyList();
    if (keyList.length > 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[페이지 로드] 잔존 TimeoutKeyList : " + JSON.stringify(keyList));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("[페이지 로드] TimeoutKeyList : 비어있음 (타이머 자동 제거 확인)");
    }
};



scwin.btn_setTimeout_onclick = function () {
    var key = par_key.getValue();
    var delay = par_delay.getValue();
    var options = {};

    if (key !== "") {
        options.key = key;
    }
    if (delay !== "") {
        options.delay = parseInt(delay);
    }

    var result = $p.setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("func 실행됨");
    }, options);

    wf_body_bottom.getObj("scwin").setReturnValue("setTimeout 반환값(key) : " + result);
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + typeof result);
}



scwin.btn_setTimeout_debounce_onclick = function () {
    var key = "debounce_test";

    $p.setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("1번째 호출 실행됨");
    }, {key: key, delay: 500});

    $p.setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("2번째 호출 실행됨");
    }, {key: key, delay: 500});

    $p.setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("3번째 호출 실행됨 (디바운스: 마지막만 실행)");
    }, {key: key, delay: 500});

    wf_body_bottom.getObj("scwin").setReturnValue("디바운스 테스트: 동일 키로 3회 호출, 500ms 후 결과 확인");
}



scwin.btn_reinitialize_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("reinitialize 실행 → 페이지 새로고침 후 TimeoutKeyList 확인");
    $p.reinitialize();
}
